}
return true;

const isEnabled = typeof window.__ai4a11ySpaFocus !== 'undefined' && window.__ai4a11ySpaFocus.enabled;
if (!isEnabled) return true;

const region = document.getElementById('ai4a11y-spa-focus-region');
if (!region) return false;
if (region.getAttribute('aria-live') !== 'assertive') return false;
if (region.getAttribute('aria-atomic') !== 'true') return false;

const style = window.getComputedStyle(region);
if (style.position !== 'absolute') return false;
if (style.overflow !== 'hidden') return false;
const rect = region.getBoundingClientRect();
if (rect.width > 1 || rect.height > 1) return false;

const announced = globalThis.__verifyAnnounced || [];
if (!announced.includes('Announcing page changes in this app')) return false;
return true;

const isEnabled = typeof window.__ai4a11ySpaFocus !== 'undefined' && window.__ai4a11ySpaFocus.enabled;
if (!isEnabled) return true;

const navAnalytics = document.getElementById('nav-analytics');
const main = document.getElementById('main');
const region = document.getElementById('ai4a11y-spa-focus-region');
if (!navAnalytics || !main || !region) return false;

// Navigate via link click (triggers history.pushState + view update)
navAnalytics.click();
await new Promise(r => setTimeout(r, 250));

const focusMoved = (document.activeElement === main);
const hasTabindex = (main.getAttribute('tabindex') === '-1');
const regionText = (region.textContent || '').trim();
