// Put page back at the end
if (typeof window.resetPageState === 'function') window.resetPageState();
document.activeElement?.blur();
await new Promise(r => setTimeout(r, 250));

return focusMoved && hasTabindex && announcedExpected;

const isEnabled = typeof window.__ai4a11ySpaFocus !== 'undefined' && window.__ai4a11ySpaFocus.enabled;
