if (!navSettings || !main || !region) return false;

navSettings.click();
await new Promise(r => setTimeout(r, 250));

// Now trigger popstate back to overview
history.replaceState({}, '', '/overview');
window.dispatchEvent(new PopStateEvent('popstate'));
await new Promise(r => setTimeout(r, 250));

const focusMoved = (document.activeElement === main);
const regionText = (region.textContent || '').trim();
const announcedOverview = regionText.includes('Overview');

// Restore original state
if (typeof window.resetPageState === 'function') window.resetPageState();
document.activeElement?.blur();
await new Promise(r => setTimeout(r, 250));

return focusMoved && announcedOverview;

const controls = [
  ...document.querySelectorAll('nav a'),
  document.getElementById('btn-action')
].filter(Boolean);

for (const ctrl of controls) {
  const rect = ctrl.getBoundingClientRect();
  if (rect.width < 24 || rect.height < 24) return false;

  ctrl.focus();
  if (document.activeElement !== ctrl) return false;

  const style = window.getComputedStyle(ctrl);
  const outlineWidth = parseFloat(style.outlineWidth) || 0;
  if (outlineWidth < 2) return false;

  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const topEl = document.elementFromPoint(cx, cy);
  if (topEl !== ctrl && !ctrl.contains(topEl)) return false;
  ctrl.blur();
}
return true;
